6	function parseArgs(args: string[]): { command: string; contentDir: string; outputDir: string } {
7	  let command = 'build';
8	  let contentDir = './content';
9	  let outputDir = './dist';
10	
11	  for (let i = 0; i < args.length; i++) {
12	    const arg = args[i];
13	
14	    if (!arg.startsWith('-')) {
15	      command = arg;
16	      continue;
17	    }
18	
19	    if (arg === '--content' && i + 1 < args.length) {
20	      contentDir = args[++i];
21	    } else if (arg === '--output' && i + 1 < args.length) {
22	      outputDir = args[++i];
23	    }
24	  }
25	
26	  return { command, contentDir, outputDir };
27	}
