29	async function main(): Promise<void> {
30	  const args = process.argv.slice(2);
31	  const { command, contentDir, outputDir } = parseArgs(args);
32	
33	  if (command !== 'build') {
34	    console.error(`Unknown command: ${command}`);
35	    process.exit(1);
36	  }
37	
38	  const resolvedContentDir = path.resolve(contentDir);
39	  const resolvedOutputDir = path.resolve(outputDir);
40	
41	  try {
42	    const generator = new SiteGenerator({
43	      contentDir: resolvedContentDir,
44	      outputDir: resolvedOutputDir,
45	    });
46	
47	    await generator.build();
48	  } catch (error) {
49	    console.error('Error building site:', error instanceof Error ? error.message : String(error));
50	    process.exit(1);
51	  }
52	}
