85	    }
86	    h1, h2, h3, h4, h5, h6 { margin-top: 1.5em; }
87	    code {
88	      background: #f0f0f0;
89	      padding: 2px 6px;
90	      border-radius: 3px;
91	      font-family: 'Courier New', monospace;
92	    }
93	    pre {
94	      background: #f5f5f5;
95	      padding: 10px;
96	      border-radius: 5px;
97	      overflow-x: auto;
98	    }
99	    pre code { background: none; padding: 0; }
100	    a { color: #0066cc; text-decoration: none; }
101	    a:hover { text-decoration: underline; }
102	    .nav { margin-bottom: 20px; }
103	    .nav a { margin-right: 15px; }
104	  </style>
105	</head>
106	<body>
107	  <div class="nav">
108	    <a href="index.html">← Home</a>
109	  </div>
110	  <h1>${this.escapeHtml(title)}</h1>
111	  <div>${content}</div>
112	</body>
113	</html>`;
114	  }
115	
116	  private generateIndexHtml(pages: PageMetadata[]): string {
117	    const pagesList = pages
118	      .map(
119	        (page) => `    <li>
120	      <a href="${this.escapeHtml(page.url)}">${this.escapeHtml(page.title)}</a>
121	      ${page.date ? `<span style="color: #666; margin-left: 10px;">${this.escapeHtml(page.date)}</span>` : ''}
122	      ${page.tags.length > 0 ? `<div style="margin-top: 5px;"><small>${page.tags.map((tag) => `<span style="display: inline-block; background: #eee; padding: 2px 8px; border-radius: 3px; margin-right: 5px;">${this.escapeHtml(tag)}</span>`).join('')}</small></div>` : ''}
123	    </li>`
124	      )
125	      .join('\n');
126	
127	    return `<!DOCTYPE html>
128	<html lang="en">
129	<head>
130	  <meta charset="UTF-8">
131	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
132	  <title>Static Site</title>
133	  <style>
134	    body {
135	      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
136	      line-height: 1.6;
137	      max-width: 800px;
138	      margin: 0 auto;
139	      padding: 20px;
140	      color: #333;
141	    }
142	    h1 { margin-top: 0; }
143	    ul { list-style: none; padding: 0; }
144	    li {
145	      padding: 15px;
146	      border: 1px solid #eee;
147	      margin-bottom: 10px;
148	      border-radius: 5px;
149	    }
150	    li:hover { background: #f9f9f9; }
151	    a { color: #0066cc; text-decoration: none; }
152	    a:hover { text-decoration: underline; }
153	  </style>
154	</head>
155	<body>
156	  <h1>Pages</h1>
157	  ${pages.length > 0 ? `<ul>\n${pagesList}\n  </ul>` : '<p>No pages found.</p>'}
158	</body>
159	</html>`;
160	  }
161	
162	  private escapeHtml(text: string): string {
163	    return text
164	      .replace(/&/g, '&amp;')
165	      .replace(/</g, '&lt;')
166	      .replace(/>/g, '&gt;')
167	      .replace(/"/g, '&quot;')
168	      .replace(/'/g, '&#39;');
169	  }
170	
171	  async build(): Promise<void> {
172	    this.ensureDir(this.outputDir);
173	
174	    const markdownFiles = this.getMarkdownFiles();
175	    const pages: PageMetadata[] = [];
176	
177	    for (const file of markdownFiles) {
178	      const filePath = path.join(this.contentDir, file);
179	      const content = fs.readFileSync(filePath, 'utf-8');
180	      const parsed = await parseMarkdown(content);
181	
182	      const title = parsed.frontmatter.title || file.replace('.md', '');
183	      const slug = file.replace('.md', '.html');
184	      const outputPath = path.join(this.outputDir, slug);
185	
186	      const templateName = parsed.frontmatter.template ? String(parsed.frontmatter.template) : undefined;
187	      const layoutName = parsed.frontmatter.layout ? String(parsed.frontmatter.layout) : undefined;
188	
189	      const pageHtml = this.renderPageWithTemplate(
190	        title,
191	        parsed.html,
192	        templateName,
193	        layoutName,
194	        parsed.frontmatter
195	      );
196	
197	      fs.writeFileSync(outputPath, pageHtml);
198	
199	      pages.push({
200	        filename: file,
201	        title,
202	        date: parsed.frontmatter.date ? String(parsed.frontmatter.date) : undefined,
203	        tags: Array.isArray(parsed.frontmatter.tags)
204	          ? parsed.frontmatter.tags.map((tag) => String(tag))
205	          : [],
206	        url: slug,
207	        template: templateName,
208	        layout: layoutName,
209	      });
210	    }
211	
212	    const indexPath = path.join(this.outputDir, 'index.html');
213	    fs.writeFileSync(indexPath, this.generateIndexHtml(pages));
214	
215	    console.log(`✓ Generated ${pages.length} page(s) to ${this.outputDir}`);
216	  }
217	}
